INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'Biology', 'Unit 5', 'Molarum Grade 10 — Biology Human Biology', 'Source-grounded Molarum Grade 10 Biology questions for Human Biology.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('35cc7d8d-e5f3-4e97-82d7-ba7a21922158'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Which statement best describes the importance of sodium ions in the human body?', 'They help regulate body fluid balance and nerve impulse transmission', 'Sodium ions help maintain fluid balance, blood volume, and are essential for transmission of nerve impulses and muscle contraction as described in the section on sodium ions.', 0),('09a18b72-0f66-4574-822d-655b318159cc'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which statement best describes the role of potassium ions in the body?', 'They maintain intracellular fluid and support nerve impulses', 'Potassium is the major intracellular cation and is essential for maintaining cell potential and nerve function.', 1),('c080c2c3-5bf1-4431-8269-7c564a31064a'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which function is primarily associated with iron ions in the human body?', 'Oxygen transport in hemoglobin', 'Iron is a key component of hemoglobin and myoglobin, enabling oxygen transport and storage.', 2),('0b0826ca-4f9c-4250-821e-bbe46096a176'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Copper ions function as a trace element in several enzymes and in iron metabolism. Which statement best reflects this role?', 'They act as cofactors for enzymes involved in iron metabolism and antioxidant defense', 'Copper is a trace element required for several enzymes, including those involved in iron metabolism (ceruloplasmin) and antioxidant enzymes.', 3),('bb8fe146-6174-4db8-8477-48a35beb8595'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which of the following are common dietary sources of iodide ions and important for thyroid hormone production?', 'Iodized salt, fish, and dairy products', 'Iodide is obtained from iodized salt, seafood, and dairy, and is essential for thyroid hormone synthesis.', 4),('91c09514-c81c-48e0-8e03-1d2c534ce157'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'true_false', 'Potassium ions are the major intracellular cation and are essential for nerve impulse transmission.', 'True', 'Potassium is the main intracellular cation and plays a key role in membrane potential and nerve impulses.', 5),('b3c7bd6f-0b8d-4c46-853c-0aaa873d6d64'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Name two physiological roles of calcium ions in the human body.', 'bone formation and muscle contraction', 'Calcium ions are essential for bone mineralization and muscle contraction; they also participate in blood clotting and signaling.', 6),('93958695-40de-4491-844c-8cb3bfb0bf48'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Explain one major role of chloride ions in the body and a primary dietary source.', 'role: maintains electrical neutrality and fluid balance; source: table salt (sodium chloride) in the diet', 'Chloride ions help maintain osmotic balance, contribute to stomach acid formation, and accompany sodium in fluid balance; primary dietary source is table salt.', 7),('1888bffb-5568-4ed0-83f4-f45eaf4215cb'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Daily calcium requirement is 1000 mg. If a student consumes 600 mg from one meal and 350 mg from a second meal, calculate the total calcium intake and the percentage of the daily requirement met. Show the method and final unit.', 'Total intake = 950 mg; Percentage of daily requirement = 95%', 'Sum of intakes: 600 mg + 350 mg = 950 mg. 950/1000 = 0.95 → 95% of daily calcium requirement.', 8),('2d3f3ba3-676f-4dc8-8a87-4607570d29c7'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Daily sodium recommendation is 1500 mg. If a person consumes 3 meals with equal sodium content, how many milligrams of sodium are consumed per meal? Show the method and final unit.', 'Per meal: 500 mg', '1500 mg / 3 meals = 500 mg per meal.', 9),('daeef756-2597-43e3-866a-698069bdd7ef'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'What is one key importance of sodium ions in the human body?', 'Maintain fluid balance and nerve function', 'Sodium ions help regulate fluid balance, enable nerve impulse transmission, and support muscle function.', 10),('add147ff-aa31-4642-81ab-005552345594'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'true_false', 'High sodium intake can contribute to high blood pressure.', 'True', 'Excess sodium can raise blood volume and pressure.', 11),('ba5f9071-21e4-42da-8303-a0b34ccfa0fe'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which ion is most directly involved in maintaining proper nerve impulse transmission and muscle function?', 'Potassium ions', 'Potassium ions work with sodium to regulate nerve impulses and muscle contraction.', 12),('a71da7af-ed4b-4227-846c-0aa6b17eed24'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Chloride ions are primarily obtained from which dietary source?', 'Salt in the diet', 'Chloride ions come mainly from dietary salt; they help with digestion and fluid balance.', 13),('87f2d3b7-fabd-42d0-8e05-818c94fcbe82'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which ion is essential for oxygen transport in blood?', 'Iron ions', 'Iron in hemoglobin binds oxygen and enables transport.', 14),('6a32d338-e34e-4f2a-82fe-7348073a0ece'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Name one role of calcium ions in the human body.', 'Bone formation', 'Calcium ions are essential for bone and teeth structure and function.', 15),('43badf1a-a597-4426-8cde-ff8cacfa8620'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Explain two roles of chloride ions in the body.', 'Digestion (as part of hydrochloric acid in the stomach) and fluid/blood volume regulation', 'Chloride ions help form gastric acid for digestion and assist in maintaining fluid balance and blood volume.', 16),('c8c38caa-af85-4d91-8d31-2bb69c7e4ba4'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'The daily sodium requirement is 1500 mg. A person consumes 600 mg at breakfast and 350 mg at lunch. How many milligrams remain to meet the daily requirement?', '550 mg', 'Remaining sodium needed = 1500 mg − (600 mg + 350 mg) = 550 mg.', 17),('88defa4b-d766-4ffc-823d-e114d7223fa4'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'In hemoglobin, which oxidation state of iron is most commonly bound to oxygen?', 'Fe2+', 'Fe2+ (ferrous) is the state that binds oxygen in hemoglobin.', 18),('0ffa77ae-ca73-460d-8aaf-3cbeff2bad49'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Calcium daily requirement: 1000 mg. Dairy sources provide 250 mg, leafy greens 120 mg, and fortified foods 50 mg. How much more calcium is needed to reach the daily requirement?', '580 mg', 'Remaining = 1000 mg − (250 mg + 120 mg + 50 mg) = 580 mg.', 19),('57cda09a-d0c0-4d0d-876c-47b845019c3c'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'What is a primary role of sodium ions in the human body?', 'They help transmit nerve impulses', 'Sodium ions are essential for nerve impulse transmission and maintaining fluid balance. They depolarize nerve membranes to propagate electrical signals.', 20),('28196c43-8570-40b6-8ce0-41fefa8b673b'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which statement best describes the role and source of chloride ions in the body?', 'They help form hydrochloric acid in the stomach and help maintain fluid balance; sources include table salt', 'Chloride ions help form hydrochloric acid in the stomach and contribute to fluid and acid-base balance; common dietary source is NaCl (table salt).', 21),('00f62607-8508-4935-8be9-37c044ce9ed5'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which function is most closely associated with potassium ions in the body?', 'Nerve impulses and muscle function', 'Potassium ions help regulate nerve signals and muscle contractions, including heart muscle. They help maintain electrochemical gradients.', 22),('13cffc7a-df4a-470d-8457-da63ab5e7cd7'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which is a common dietary source of iodide ions and why are they needed?', 'Iodized salt; for thyroid hormone synthesis', 'Iodide is required for thyroid hormones. Iodized salt is a common dietary source to prevent deficiency.', 23),('76c9ff98-e306-4990-88a2-e88540b8033a'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Iron ions are a key component of which molecules in the blood?', 'Hemoglobin and myoglobin', 'Iron ions are central to hemoglobin in red blood cells and myoglobin in muscle tissue, aiding oxygen transport and storage.', 24),('dccd7552-8840-495b-8c20-a7655cf66743'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'State two key roles of calcium ions in the human body.', 'Calcium is needed for bone and teeth formation; it is essential for blood clotting and muscle function', 'Calcium ions support bone/teeth structure and participate in blood clotting and muscle contraction.', 25),('647d30d0-78c5-4a63-8dc0-a34b252d0268'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'true_false', 'High sodium intake can lead to increased blood pressure.', 'True', 'Excess sodium intake is associated with higher risk of elevated blood pressure and hypertension.', 26),('6fcf079b-36db-403b-8d29-fcb59c3796ea'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Name one primary function of chloride ions in the body.', 'Chloride ions help form hydrochloric acid in the stomach and help maintain fluid and acid-base balance.', 'Chloride ions participate in digestion (forming stomach acid) and help regulate fluid balance and pH.', 27),('0066312d-260d-493c-86bb-ce63885a3fe1'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Daily iron requirement for an adult is 18 mg. If a meal provides 7 mg of iron, how many additional mg are needed to reach the daily requirement? Show your method and final unit.', '11 mg', '18 mg required minus 7 mg obtained equals 11 mg remaining.', 28),('074c19f0-73ea-4092-8955-8e4f84d6ed2f'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Daily copper requirement is 0.9 mg. If a person consumes 0.45 mg per day, calculate the daily deficit and express the result in mg. Show your method and final unit.', '0.45 mg', '0.9 mg required minus 0.45 mg intake equals 0.45 mg deficit.', 29),('84d63018-c29d-4fd1-82ed-a4e5dcbdb033'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which statement best describes the role of sodium (Na+) ions in the human body as discussed in Unit 3: Biochemical Molecules?', 'They help regulate fluid balance and nerve impulse transmission.', 'Sodium ions help maintain extracellular fluid volume and osmotic balance; they also participate in generating nerve impulses and muscle action potentials.', 30),('f1db64bb-7fad-4655-8eb6-c322432e77de'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which function is associated with chloride ions (Cl−) in the human body as described in Unit 3?', 'Chloride ions help regulate acid-base balance and fluid balance in body fluids.', 'Chloride ions contribute to maintaining osmotic balance and pH in body fluids and are components of gastric acid (HCl) in digestion.', 31),('503f79e6-96b3-4a29-8053-24fd98982d7b'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'What is the primary biological role of iron ions (Fe2+/Fe3+) in humans as described in Unit 3?', 'They are essential for oxygen transport in hemoglobin and myoglobin.', 'Iron ions are crucial for binding oxygen in hemoglobin and myoglobin, enabling oxygen transport and storage in muscles; iron is also a cofactor for many enzymes.', 32),('e2600128-6635-4aa6-8def-f961f07da169'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which of the following is a key role of potassium ions (K+) in human physiology as described in Unit 3?', 'They regulate muscle and nerve function by maintaining resting potential and fluid balance.', 'Potassium ions are crucial for repolarization during nerve impulses and help maintain cellular resting potential and intracellular fluid balance.', 33),('58a4be7e-48cc-4a13-8151-d042949c07fe'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which role is commonly attributed to calcium ions (Ca2+) in the human body as per Unit 3 discussions?', 'They enable muscle contraction and bone health; also play a role in blood clotting.', 'Calcium ions are essential for muscle contraction, bone mineralization, and blood clotting processes; they also act as a second messenger in many pathways.', 34),('90d95081-774d-47b1-8c48-7be972d1e623'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'multiple_choice', 'Which statement best reflects the role and requirement of iodide ions (I−) in humans as described in Unit 3?', 'Iodide ions are essential for thyroid hormone synthesis and metabolism; maintaining dietary iodine is important.', 'Iodide is required for thyroid hormone production (T3/T4). Adequate iodine intake is important for normal thyroid function and metabolism.', 35),('00e44544-151f-49fc-8ab1-0337b7e9b30f'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'true_false', 'Hydrogen ions (H+) influence the pH of body fluids, which affects enzyme activity and metabolism.', 'True', 'Hydrogen ion concentration determines pH; small changes can significantly affect enzyme structure and function.', 36),('28904579-4227-4913-8a56-96fde479df8f'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Briefly describe two essential roles of potassium ions in human physiology.', 'Two essential roles: (1) maintaining resting membrane potential and aiding nerve impulse transmission; (2) regulating muscle contractions and fluid balance inside cells.', 'Potassium ions are critical for neuronal signaling and muscular function, including heart muscle activity and intracellular osmotic balance.', 37),('89b52eb3-edf5-4604-85fe-ca2912bf1bb7'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'Calculate the number of moles of calcium ions (Ca2+) in 0.5 liters of blood plasma if the Ca2+ concentration is 1.25 millimoles per liter (mM). Show your method and final unit.', '6.25e-4 mol; method: multiply concentration by volume: 1.25e-3 mol/L * 0.5 L = 6.25e-4 mol; final unit: mol.', 'Concentration (C) in mol/L times volume (V) in L gives moles (n). 1.25 mM = 1.25e-3 mol/L; V=0.5 L; n=6.25e-4 mol.', 38),('5064b052-61e4-4e41-804f-b6582b995ca7'::uuid, 'fdd1bf3c-18fb-42c1-8287-a00900f5bb80'::uuid, 'fill_blank', 'A person consumes 3500 mg of sodium daily. The recommended daily intake is 1500 mg. Calculate the percentage of the recommended intake that this amount represents and state the reason for any excess.', '233.3% of the recommended daily intake; method: (3500/1500)*100 = 233.3%; excess due to higher intake than recommended.', '3500 mg is about 2.33 times the 1500 mg daily recommendation; excess sodium intake can be associated with health risks if sustained.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
